def permute(nk, rho):
    state=[nk, rho, 1<<65]
    for index in (*range(4), *range(4, 9), *range(60, 64)):
        state=[(x+c)%P for x,c in zip(state, RC[index])]
        for column in (range(3) if index<4 or index>=60 else range(1)):
            state[column]=pow(state[column],5,P)
        state=[sum(c*x for c,x in zip(row,state))%P for row in MDS]
    return state[0]

def trunc16(x):
    return permute(x, 0) & 0xFFFF

def enc_msg(x):
    return x.to_bytes(32,"little") + (0).to_bytes(32,"little")

def build():
    return [trunc16(x) for x in range(65536)]

def rho(table, x0, cap):
    t, h, n = table[x0], table[table[x0]], 3
    while t != h:
        t, h = table[t], table[table[h]]; n += 3
        if n > cap: return None, None, n
    t = x0
    while True:
        ft, fh = table[t], table[h]; n += 2
        if ft == fh: break
        t, h = ft, fh
    if t == h: return None, None, n
    return enc_msg(t).hex(), enc_msg(h).hex(), n

def main():
    req=json.load(sys.stdin); table=build(); out=[]
    for tr in req["trials"]:
        a,b,n=rho(table, int(tr["seed"],16)&0xFFFF, 5*2**16)
        out.append({"trial":tr["trial"],"message_a_hex":a,"message_b_hex":b,"observations":{"evaluations":n}})
    print(json.dumps({"schema_version":1,"trials":out}, sort_keys=True))

if __name__=="__main__":
    main()
